import { useState, useEffect, useCallback } from 'react';

const BACKEND = 'https://content-ai-backend-2rvu.onrender.com';

export function useFollow(currentUserId, targetUserId) {
  const [following, setFollowing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [counts, setCounts] = useState({ followers: 0, following: 0 });

  // Check follow status on mount
  useEffect(() => {
    if (!currentUserId || !targetUserId || currentUserId === targetUserId) return;

    fetch(`${BACKEND}/api/follow/status?follower_id=${currentUserId}&following_id=${targetUserId}`)
      .then(r => r.json())
      .then(data => setFollowing(data.following))
      .catch(() => {});
  }, [currentUserId, targetUserId]);

  // Fetch follower/following counts for target user
  useEffect(() => {
    if (!targetUserId) return;

    fetch(`${BACKEND}/api/follow/counts?user_id=${targetUserId}`)
      .then(r => r.json())
      .then(data => setCounts({ followers: data.followers || 0, following: data.following || 0 }))
      .catch(() => {});
  }, [targetUserId]);

  const toggle = useCallback(async () => {
    if (!currentUserId || !targetUserId || loading) return;

    setLoading(true);
    try {
      const res = await fetch(`${BACKEND}/api/follow/toggle`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ follower_id: currentUserId, following_id: targetUserId })
      });
      const data = await res.json();
      setFollowing(data.following);
      // Update counts optimistically
      setCounts(prev => ({
        ...prev,
        followers: data.following ? prev.followers + 1 : prev.followers - 1
      }));
    } catch (err) {
      console.error('Follow toggle failed:', err);
    } finally {
      setLoading(false);
    }
  }, [currentUserId, targetUserId, loading]);

  return { following, loading, counts, toggle };
}
